import { io } from 'socket.io-client';

const getSocketURL = () => {
  if (process.env.REACT_APP_API_URL) {
    return process.env.REACT_APP_API_URL.replace('/api', '');
  }
  const host = window.location.hostname;
  if (host === 'localhost' || host === '127.0.0.1') return 'http://localhost:5000';
  return `http://${host}:5000`;
};

// Connexion lazy : ne se connecte que quand on appelle connect()
const socket = io(getSocketURL(), {
  autoConnect: false,       // Ne pas se connecter avant login
  reconnection: true,
  reconnectionDelay: 2000,
  reconnectionAttempts: 5,
});

// Appelé après login avec l'id utilisateur pour rejoindre la salle personnalisée
export const connectSocket = (userId) => {
  if (!socket.connected) {
    socket.connect();
    socket.once('connect', () => {
      socket.emit('join', userId);
    });
  }
};

// Appelé lors du logout
export const disconnectSocket = () => {
  if (socket.connected) socket.disconnect();
};

export default socket;
